using System.Collections.Generic;
using ReyDesk.Windows.Settings;

namespace ReyDesk.Windows.Localization;

/// <summary>
/// Hand-rolled string table (English, Persian), not
/// WinUI's .resw/MRT resource system. MRT resource resolution largely assumes MSIX
/// package identity, which this unpackaged app deliberately doesn't have - a plain
/// dictionary switched at runtime is more reliable here and still gives genuinely
/// instant language switching, including FlowDirection for RTL languages (spec §24).
///
/// /// </summary>
internal static class Strings
{
    public static AppLanguage Current { get; set; } = AppLanguage.English;

    public static bool IsRtl(AppLanguage language) => language is AppLanguage.Persian;

    public static string Get(string key)
    {
        if (!Table.TryGetValue(key, out var row)) return key;
        return RtlSafe(row[(int)Current]);
    }

    // U+200F keeps a leading Latin word (ReyDesk) from flipping the paragraph direction in FA.
    internal static string RtlSafe(string text) =>
        IsRtl(Current) && text.StartsWith("ReyDesk") ? "‏" + text : text;

    // Column order fixed to AppLanguage's declaration order: En, Fa.
    private static readonly Dictionary<string, string[]> Table = new()
